import React, { createContext, useState, useContext, useEffect } from 'react';
import authService from '../services/authService';

const AuthContext = createContext();

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const initializeAuth = () => {
      try {
        const token = authService.getToken();
        const storedUser = authService.getCurrentUser();
        
        console.log('Auth initialization:', { token: !!token, storedUser: !!storedUser });
        
        if (token && storedUser) {
          setUser(storedUser);
        }
      } catch (error) {
        console.error('Error initializing auth:', error);
      } finally {
        setLoading(false);
      }
    };

    initializeAuth();
  }, []);

  const login = async (credentials) => {
    try {
      const userData = await authService.login(credentials);
      setUser(userData);
      return userData;
    } catch (error) {
      throw error;
    }
  };

  const register = async (userData) => {
    try {
      const result = await authService.register(userData);
      return result;
    } catch (error) {
      throw error;
    }
  };

  const logout = () => {
    authService.logout();
    setUser(null);
  };

  const isAuthenticated = () => {
    try {
      const result = authService.isAuthenticated();
      console.log('isAuthenticated called, result:', result);
      return result;
    } catch (error) {
      console.error('Error in isAuthenticated:', error);
      return false;
    }
  };

  const hasRole = (role) => {
    try {
      const result = authService.hasRole(role);
      console.log('hasRole called with:', role, 'result:', result);
      return result;
    } catch (error) {
      console.error('Error in hasRole:', error);
      return false;
    }
  };

  const value = {
    user,
    login,
    register,
    logout,
    isAuthenticated,
    hasRole,
    loading
  };

  console.log('AuthContext value:', { 
    user: !!user, 
    loading, 
    isAuthenticated: typeof isAuthenticated,
    hasRole: typeof hasRole 
  });

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};
